    assert.equal(report.submission_context,'mission');assert.equal(before.completed_tests,0);assert.equal(after.completed_tests,1);
    assert.equal(after.carryover_remaining_tests,before.carryover_remaining_tests-1);
    // One old task remains; only the mission report exists. This must not pay a regular test debt.
