    const bypass=await status();assert.equal(bypass.mode,'member');assert.equal(bypass.carryover_remaining_tests,0);
    const owned=(await q(`select id from public.campaigns where owner_id='${owner}' order by slot_number limit 1`)).id;
    await db.exec(`set request.jwt.claim.sub='${owner}';set role authenticated`);
    const resumed=(await q(`select public.resume_campaign('${owned}') r`)).r;
    await db.exec('reset role;reset request.jwt.claim.sub');assert.equal(resumed.status,'open');
    return {before:brief(before),after:brief(after),report,response:{success:response.success,submission_context:response.submission_context},
      alternateFixtureWithOneOldDebt:brief(bypass),resumedStatus:resumed.status};
  });
  await scenario('UI defect reproduced: completed compact card hides remaining debt',async()=>{
    await policy(0,true);await checkpoint(1,8);await available(5);await events(0,5);const s=await status();
