    assert.equal((await status()).carryover_ready,false);return {...state,status:brief(await status()),gapDays:39,coverageDays:60};
  });
  await scenario('Coverage defect reproduced: reapplying 066 replaces current getter and finalizer',async()=>{
    const definitions=async()=>await q(`select md5(pg_get_functiondef('public.get_daily_task_status(uuid,date)'::regprocedure)) getter,md5(pg_get_functiondef('public._apply_daily_inactivity_penalty(date)'::regprocedure)) finalizer`);
