await scenario('C03: 40-day covered gap recovers in bounded batches with persistent progress and idempotence', async () => {
  // Checkpoint 40 days ago with debt 8 for owner
  await policy(40, true);
  await checkpoint(40, 8);

  // Initial check: sealed records > day-40 is 0, carryover_ready is false
  const initialSealed = (await q(`select count(*)::int c from public.user_daily_tasks where user_id='${owner}' and task_date>${today}-40 and finalized_at is not null`)).c;
  assert.equal(initialSealed, 0);
  assert.equal((await status()).carryover_ready, false);

  // Run 1: First batch of 31 days
  const batch1Days = (await q('select public.apply_daily_inactivity_penalty(31) c')).c;
  assert.ok(batch1Days > 0, `Batch 1 must process days (got ${batch1Days})`);

  const sealedAfterBatch1 = (await q(`select count(*)::int c from public.user_daily_tasks where user_id='${owner}' and task_date>${today}-40 and finalized_at is not null`)).c;
  assert.equal(sealedAfterBatch1, 31, 'Batch 1 must seal exactly 31 days of persistent progress');

  // Run 2: Second batch recovers remaining 8 days up to yesterday
  const batch2Days = (await q('select public.apply_daily_inactivity_penalty(31) c')).c;
  assert.ok(batch2Days > 0, `Batch 2 must process remaining days (got ${batch2Days})`);

  const sealedAfterBatch2 = (await q(`select count(*)::int c from public.user_daily_tasks where user_id='${owner}' and task_date>${today}-40 and finalized_at is not null`)).c;
  assert.equal(sealedAfterBatch2, 39, 'Batch 2 must complete all 39 missing days');

  const finalStatus = await status();
  assert.equal(finalStatus.carryover_ready, true, 'Today must now have carryover_ready=true');
  assert.equal(finalStatus.history_ready, true);

  // Run 3: Repeat run idempotence check (must not duplicate penalty or deduct credits)
  const creditsBefore = (await q(`select credits from public.profiles where id='${owner}'`)).credits;
  const batch3Days = (await q('select public.apply_daily_inactivity_penalty(31) c')).c;
  const creditsAfter = (await q(`select credits from public.profiles where id='${owner}'`)).credits;
  assert.equal(creditsAfter, creditsBefore, 'Repeat run must NOT deduct additional credits');
  assert.equal((await status()).carryover_ready, true, 'Repeat run must keep carryover_ready=true');

  return { sealedAfterBatch1, sealedAfterBatch2, finalCarryoverReady: finalStatus.carryover_ready };
});

